@startuml

class HospitalHouseMD {
  + Name : string
  + Address : string
}

class Patient {
  + Name : string
  + ID : string
  + Symptoms : string
}

class Doctor {
  + Name : string
  + Specialization : string
  + ID : string
}

class HeadDoctor {
  + AuthorityLevel : int
}

class Diagnosis {
  + Description : string
  + DateMade : date
  + IsApproved : boolean
}

class Treatment {
  + Name : string
  + Description : string
  + CurrentStage : int
}

class ConsentForm {
  + SignatureDate : date
  + IsActive : boolean
}

class Illness {
  + Name : string
  + PriorityScore : PriorityScore
}

enum PriorityScore {
  High
  Low
}

class TreatmentDatabase {
  + EntryCount : int
}

Doctor "1..*" -- "0..*" Patient
Doctor "1" -- "0..*" Diagnosis
HeadDoctor "1" -- "0..*" Diagnosis : approves
Patient "1" -- "0..*" Diagnosis
Diagnosis "1" -- "1..*" Treatment
Illness "1" -- "0..*" Diagnosis
Illness "1" -- "0..*" Treatment
TreatmentDatabase "1" -- "0..*" Treatment
Patient "1" -- "0..*" ConsentForm
ConsentForm "0..1" -- "1..*" Treatment : governs
HospitalHouseMD "1" -- "1" TreatmentDatabase
HospitalHouseMD "1" -- "1..*" Patient

@enduml

